export const IQ_CATEGORIES = [...new Set(IQ_QUESTIONS.map(question=>question.category))]

export function mergeIqHistory(history,questions) {
  const known=new Set(IQ_QUESTIONS.map(q=>q.id))
  const combined=[...(Array.isArray(history)?history:[]),...(Array.isArray(questions)?questions:[])]
  return [...new Set(combined.reverse().filter(question=>known.has(question)))].reverse()
}

export function selectIqQuestions(count,history=[],randomIndex=max=>Math.floor(Math.random()*max),subject='') {
  if(subject!==''&&!IQ_CATEGORIES.includes(subject))throw new RangeError('Invalid subject')
  const available=IQ_QUESTIONS.filter(q=>!subject||q.category===subject)
  if(!Number.isInteger(count)||count<1||count>available.length)throw new RangeError('Invalid question count')
  const seen=mergeIqHistory([],history),used=new Set(seen)
  const fresh=available.filter(question=>!used.has(question.id))
  const repeats=seen.map(id=>available.find(question=>question.id===id)).filter(Boolean)
  const selected=[],categories=new Map()
  while(selected.length<count){
    const pool=fresh.length?fresh:repeats
    const least=Math.min(...pool.map(q=>categories.get(q.category)||0))
    const candidates=pool.filter(q=>(categories.get(q.category)||0)===least)
    const question=fresh.length?candidates[randomIndex(candidates.length)]:candidates[0]
    pool.splice(pool.indexOf(question),1)
    selected.push(question);categories.set(question.category,(categories.get(question.category)||0)+1)
  }
  return selected.map(question=>{
    const options=question.answers.map((text,index)=>({text,index}))
    for(let i=options.length-1;i>0;i--){const j=randomIndex(i+1);[options[i],options[j]]=[options[j],options[i]]}
    return {...question,answers:options.map(option=>option.text),correct:options.findIndex(option=>option.index===question.correct)}
  })
}
